entries[54588] = { ["name"] = "Verkohlte Zwielichtschuppe", ["text"] = "Heroisch\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Verkohlte Zwielichtschuppe (1)\nSchmuck\nErhöht Eure Tempowertung um + 6.\nAnlegen: Eure schadensverursachenden Zauber haben eine Chance, Euch 15 Sek. lang 20 Zaubermacht zu gewähren. (Procchance: 10%, 50s Abklingzeit)\nVerkaufspreis:" }
entries[54589] = { ["name"] = "Leuchtende Zwielichtschuppe", ["text"] = "Heroisch\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Leuchtende Zwielichtschuppe (1)\nSchmuck\n+4 Intelligenz\nBenutzen: Für die nächsten 15 Sek. wird jedes Mal, wenn einer Eurer direkten Heilzauber ein Ziel heilt, ein Effekt hervorgerufen, der das Ziel und seine Verbündeten innerhalb von 10 Metern 6 Sek. lang pro Sekunde um 1 heilt. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[54590] = { ["name"] = "Geschärfte Zwielichtschuppe", ["text"] = "Heroisch\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Geschärfte Zwielichtschuppe (1)\nSchmuck\nErhöht Eure kritische Trefferwertung um + 6.\nAnlegen: Wenn Ihr Schaden verursacht, besteht eine Chance, dass Ihr 15 Sek. lang 17 Angriffskraft gewinnt. (Procchance: 35%, 45s Abklingzeit)\nVerkaufspreis:" }
entries[54591] = { ["name"] = "Versteinerte Zwielichtschuppe", ["text"] = "Heroisch\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Versteinerte Zwielichtschuppe (1)\nSchmuck\n+ 6 Vielseitigkeit\nAnlegen: Nahkampfangriffe, die Eure Gesundheit auf unter 35% verringern, gewähren Euch 10 Sek. lang 29 Ausweichen. Kann maximal einmal alle 45 Sek. auftreten. (45s Abklingzeit)\nVerkaufspreis:" }
