entries[54797] = { ["name"] = "Fliegender Frostteppich", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen fliegenden Frostteppich oder gibt ihn wieder frei. Dieses Fortbewegungsmittel passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Schneiderei von Nordend (1)\nBenötigt Unerfahrenes Reiten\n\n\"Ich kann mich noch an meinen ersten fliegenden Teppich erinnern... Yetihaar und Leinen. Keineswegs so angenehm wie dieser hier. - Frozo der Wohlbekannte\"\nBeruf:\nSchneidern" }
entries[54798] = { ["name"] = "Muster: Fliegender Frostteppich", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen fliegenden Frostteppich näht.\nBenötigt Schneiderei von Nordend (50)\n\nFliegender Frostteppich\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen fliegenden Frostteppich oder gibt ihn wieder frei. Dieses Fortbewegungsmittel passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Schneiderei von Nordend (1)\nBenötigt Unerfahrenes Reiten\n\n\"Ich kann mich noch an meinen ersten fliegenden Teppich erinnern... Yetihaar und Leinen. Keineswegs so angenehm wie dieser hier. - Frozo der Wohlbekannte\"\nBeruf:\nSchneidernBenötigt Mondgespinst , Zaubertuch , Schwarztuch , Gefrorene Kugel (4)" }
