entries[55055] = { ["name"] = "Elementiumschildstachel", ["text"] = "Benutzen: Bringt einen Elementiumstachel an Eurem Schild an, der bei jedem Blocken 4 Schaden verursacht.\n\nDurch das Anbringen des Elementiumschildstachels wird der Gegenstand seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden." }
